#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum NumpyDType {
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    Float32,
    Float64,
    Complex64,
    Complex128,
}

#[derive(Clone, Copy, Debug)]
pub enum NumpyOperand {
    Scalar(NumpyDType),
    Array(NumpyDType),
}

impl NumpyOperand {
    /// Extract the annotated dtype from an operand, whether it is a scalar or array.
    pub fn dtype(&self) -> NumpyDType {
        match *self {
            NumpyOperand::Scalar(dt) => dt,
            NumpyOperand::Array(dt)  => dt,
        }
    }
}

/// Compute the result type of a non‐empty list of operands by promoting to the highest‐rank dtype.
pub fn result_type(operands: Vec<NumpyOperand>) -> NumpyDType {
    // We assume `operands` is non‐empty, so `max` will return `Some`.
    operands
        .iter()
        .map(|op| op.dtype())
        .max()
        .expect("operands must be non‐empty")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_result_type_scalars() {
        let ops = vec![
            NumpyOperand::Scalar(NumpyDType::Bool),
            NumpyOperand::Scalar(NumpyDType::Int32),
            NumpyOperand::Scalar(NumpyDType::Float32),
        ];
        assert_eq!(result_type(ops), NumpyDType::Float32);
    }

    #[test]
    fn test_result_type_arrays_and_scalars() {
        let ops = vec![
            NumpyOperand::Array(NumpyDType::Int16),
            NumpyOperand::Scalar(NumpyDType::Int8),
            NumpyOperand::Array(NumpyDType::Int16),
        ];
        assert_eq!(result_type(ops), NumpyDType::Int16);
    }

    #[test]
    fn test_result_type_complex_promotes() {
        let ops = vec![
            NumpyOperand::Scalar(NumpyDType::Float64),
            NumpyOperand::Array(NumpyDType::Complex64),
            NumpyOperand::Scalar(NumpyDType::Int64),
        ];
        // Complex64 > Float64 > Int64, so result should be Complex64
        assert_eq!(result_type(ops), NumpyDType::Complex64);
    }
}